#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    using namespace std;

    unsigned N;
    cin >> N;

    vector<pair<unsigned, unsigned>> takahashi;
    for (unsigned i = 0; i < N; ++i) {
        unsigned H, L;
        cin >> H >> L;
        while (!empty(takahashi) && takahashi.back().first <= H) // より早く退室するより背が低い高橋くんがいたら
            takahashi.pop_back(); // はじめに退室してもらう
        takahashi.emplace_back(H, L);
    }

    unsigned Q;
    cin >> Q;

    for (unsigned i = 0; i < Q; ++i) {
        unsigned T;
        cin >> T;
        // pair の第二要素で二分探索し、T 分より後に退出する中で最も背が高い高橋くんを見つける
        cout << ranges::upper_bound(takahashi, T, {}, &pair<unsigned, unsigned>::second)->first << endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

int main(){
	// 入力高速化
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	// イベント (時刻, タイプ, 番号 i)
	// タイプ 0 なら, 番号 i の高橋くんが離脱
	// タイプ 1 なら, クエリ番号 i に答える.
	vector<tuple<ll,int,int>> event;
	multiset<ll> st; // 高橋くんの身長の多重集合

	int n; cin >> n;
	vector<ll> h(n), l(n);

	for (int i=0; i<n; i++) {
		cin >> h[i] >> l[i];
		st.insert(h[i]);
		event.emplace_back(l[i] * 2, 0, i);
	}

	int q; cin >> q;
	vector<ll> t(q);

	for (int i=0; i<q; i++) {
		cin >> t[i];
		event.emplace_back(t[i] * 2 + 1, 1, i); 
	}

	sort(event.begin(), event.end());

	vector<ll> ans(q);
	for (auto [tim, typ, i]: event) {
		if (typ == 0) {
			st.erase(st.find(h[i])); // 多重集合から h[i] を 1 個だけ削除
		} else {
			ans[i] = *st.rbegin(); // 末尾の値を ans[i] に格納
		}
	}

	for (int i=0; i<q; i++) {
		cout << ans[i] << '\n';
	}

}
